CREATE TABLE `fabrics` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`sku` text NOT NULL,`status` text DEFAULT 'draft' NOT NULL,`current_version_id` integer,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `fabrics_sku_unique` ON `fabrics` (`sku`); CREATE INDEX `fabrics_status_idx` ON `fabrics` (`status`);
CREATE TABLE `fabric_versions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`fabric_id` integer NOT NULL,`version` integer NOT NULL,`name_en` text NOT NULL,`name_zh` text NOT NULL,`aliases_json` text DEFAULT '[]' NOT NULL,`collection` text DEFAULT '' NOT NULL,`brand` text DEFAULT '' NOT NULL,`supplier` text DEFAULT '' NOT NULL,`description` text DEFAULT '' NOT NULL,`color` text NOT NULL,`pattern` text DEFAULT '' NOT NULL,`composition` text DEFAULT '' NOT NULL,`weight_gsm` real,`usable_width_sixteenths` integer NOT NULL,`direction` text NOT NULL,`railroadable` integer DEFAULT false NOT NULL,`pattern_repeat_sixteenths` integer DEFAULT 0 NOT NULL,`match_type` text DEFAULT 'none' NOT NULL,`opacity_class` text NOT NULL,`recommended_families_json` text DEFAULT '[]' NOT NULL,`restrictions_json` text DEFAULT '[]' NOT NULL,`swatch_url` text DEFAULT '' NOT NULL,`source_file_url` text DEFAULT '' NOT NULL,`supplier_cost` real,`selling_price_reference` real,`currency` text DEFAULT 'USD' NOT NULL,`effective_from` text NOT NULL,`effective_to` text,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `fabric_versions_fabric_version_unique` ON `fabric_versions` (`fabric_id`,`version`); CREATE INDEX `fabric_versions_fabric_idx` ON `fabric_versions` (`fabric_id`);
CREATE TABLE `fabric_inventory_lots` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`fabric_id` integer NOT NULL,`lot_reference` text NOT NULL,`roll_reference` text DEFAULT '' NOT NULL,`available_length` real DEFAULT 0 NOT NULL,`uom` text DEFAULT 'yard' NOT NULL,`status` text DEFAULT 'available' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `fabric_inventory_lots_fabric_lot_unique` ON `fabric_inventory_lots` (`fabric_id`,`lot_reference`,`roll_reference`);
